<?php $pageTitle='Relatórios'; require_once __DIR__.'/../../includes/header.php';
$mensal=$pdo->query("SELECT DATE_FORMAT(data_venda,'%Y-%m') mes,SUM(total) total FROM vendas GROUP BY mes ORDER BY mes DESC LIMIT 12")->fetchAll();$top=$pdo->query('SELECT p.nome,SUM(i.quantidade) qtd,SUM(i.subtotal) total FROM venda_itens i JOIN produtos p ON p.id=i.produto_id GROUP BY p.id,p.nome ORDER BY total DESC LIMIT 10')->fetchAll();$baixo=$pdo->query('SELECT sku,nome,estoque_atual,estoque_minimo FROM produtos WHERE estoque_atual<=estoque_minimo ORDER BY estoque_atual')->fetchAll(); ?>
<div class="row g-3"><div class="col-lg-7"><div class="panel"><div class="panel-title"><h3>Faturamento por mês</h3></div><canvas id="salesChart" height="120"></canvas></div></div><div class="col-lg-5"><div class="panel"><h3>Produtos com estoque baixo</h3><table class="table mt-2"><thead><tr><th>Produto</th><th>Atual</th><th>Mín.</th></tr></thead><tbody><?php foreach($baixo as $b):?><tr><td><?=e($b['sku'].' '.$b['nome'])?></td><td><?=e($b['estoque_atual'])?></td><td><?=e($b['estoque_minimo'])?></td></tr><?php endforeach;?></tbody></table></div></div><div class="col-12"><div class="panel"><h3>Produtos mais vendidos</h3><table class="table mt-2"><thead><tr><th>Produto</th><th>Quantidade</th><th>Receita</th></tr></thead><tbody><?php foreach($top as $t):?><tr><td><?=e($t['nome'])?></td><td><?=e($t['qtd'])?></td><td><?=money($t['total'])?></td></tr><?php endforeach;?></tbody></table></div></div></div>
<script>window.addEventListener('load',()=>{new Chart(document.getElementById('salesChart'),{type:'line',data:{labels:<?=json_encode(array_reverse(array_column($mensal,'mes')))?>,datasets:[{label:'Faturamento',data:<?=json_encode(array_map('floatval',array_reverse(array_column($mensal,'total'))))?>}]},options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}})});</script><?php require __DIR__.'/../../includes/footer.php'; ?>